import 'package:flutter/material.dart';
import '../data/ingredients_data.dart';
import '../models/ingredient.dart';
import '../widgets/shared.dart';
class PantryScreen extends StatefulWidget {final Set<String> pantry;final ValueChanged<Set<String>> onChange;const PantryScreen({super.key,required this.pantry,required this.onChange});@override State<PantryScreen> createState()=>_PantryScreenState();}
class _PantryScreenState extends State<PantryScreen>{String cat='همه';@override Widget build(BuildContext c){final cats=['همه',...ingredientsMaster.map((i)=>i.category).toSet()];final list=ingredientsMaster.where((i)=>cat=='همه'||i.category==cat).toList();return ListView(padding:const EdgeInsets.all(16),children:[SectionTitle('انبار من'),SizedBox(height:40,child:ListView(scrollDirection:Axis.horizontal,children:[for(final x in cats) ChipPill(label:x,selected:cat==x,onTap:()=>setState(()=>cat=x))])),for(final i in list) CheckboxListTile(value:widget.pantry.contains(i.id),title:Text(i.name),subtitle:Text(i.category),secondary:Text(i.temperament),onChanged:(v){final s=Set<String>.of(widget.pantry);v==true?s.add(i.id):s.remove(i.id);widget.onChange(s);}),const SizedBox(height:12),PrimaryButton(text:'افزودن ماده اولیه',onPressed:()=>showModalBottomSheet(context:c,builder:(_)=>ListView(padding:const EdgeInsets.all(16),children:[for(final i in ingredientsMaster) ListTile(title:Text(i.name),onTap:(){final s=Set<String>.of(widget.pantry)..add(i.id);widget.onChange(s);Navigator.pop(c);})])))]);}}
